+        let dst = self.context.any_gpr(self.masm)?;
+
+        self.masm.v128_any_true(src.reg, writable!(dst))?;
+
+        self.context
+            .stack
+            .push(TypedReg::new(WasmValType::I32, dst).into());
+        self.context.free_reg(src);
+
+        Ok(())
+    }
